save(383,dict(paragraphs=["Inam Hussain Begg Mullick is a Kolkata poet and editor whose creative work also includes photography, music and performance. His poetry collections include Roses for the Madhouse, Winter’s Electric Architecture and The Magical Life of Inamorato, published by Writers Workshop in 2021. His work has appeared in literary journals including Usawa.","In ‘The Kingdom of Golden Dreams’, his Kabita Live poem, the city repeatedly opens into an imagined landscape. A diving cormorant, a rag-picker lifting clouds and flowers blooming among wounds bring beauty into contact with loss. Across six sections, past and present return to one another through dream, music and remembered affection."],sources=[source('The Magical Life of Inamorato — Writers Workshop','https://www.writersworkshopindia.com/books/the-magical-life-of-inamorato/',['Kolkata poet/editor; photography, composition and performance; three poetry books and 2021 publication']),source('A Couplet — poetry and contributor biography, Usawa','https://usawa.in/poetry/a-couplet-inam-hussain-mullick/',['Published poetry; literary and artistic practice; earlier collection titles'])],books=[dict(title='The Magical Life of Inamorato',detail='Poetry · Writers Workshop, 2021',url='https://www.writersworkshopindia.com/books/the-magical-life-of-inamorato/')],identity_match='Exact expanded name, Kolkata and distinctive book title match captured biography and publisher.',poems_read=[dict(id=525,title='The Kingdom of Golden Dreams',basis='Full six-section original read: street requiem, underwater kingdom, city rain, blue horses, wounds, mossy house, letters and burning snow.')],limitations=['No unverified award claims added.','No current institutional teaching appointment inferred.','Images in the poem treated as poetic constructions, not documented events.'],next_action='Independent author/editor review.'))
